select.if:
SELECT A.BOOK_DATE AS bookDate, A.BOOK_DATE AS happenDate, A.BOOKSET_ID AS booksetId, bb.BOOKSET_NAME AS booksetName, A.BUS_VOUCHNUM AS busVouchnum, A.COM_TABLE_ID AS tableId, A.TRADE_ID AS tradeId, fpd.P_TRADE_ID AS pTradeId, A.Book_Type AS bookType, A.OFFSET_FLAG AS offsetFlag, A.VOUCH_REMARK AS vouchRemark, A.VOUCH_NUM AS vouchNum, A.CREATE_USER as createUser, I.CORE_ID as coreId, I.TASK_STATUS as taskStatus FROM bok_VOUCH_MAIN A LEFT JOIN INTERF_CORE_BANK_VOUCHER I ON I.VOUCH_NUM = A.VOUCH_NUM LEFT JOIN BOK_BOOKSET bb ON BB.BOOKSET_ID = A.BOOKSET_ID LEFT JOIN trd_PRODUCT_DEAL fpd ON fpd.TRADE_ID = A.TRADE_ID WHERE EXISTS( SELECT B.VOUCH_NUM FROM BOK_VOUCH_DETAIL B WHERE B.VOUCH_NUM = A.VOUCH_NUM
AND ( B.BUSI_ID LIKE CONCAT('%' , #{busiId} , '%') )
) AND bb.BOOKSET_TYPE in (#{booksetType} ,#{booksetType2})
AND A.BOOKSET_ID IN
#{item}
AND A.COM_TABLE_ID IN
#{tableId}
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
AND A.TRADE_ID LIKE CONCAT('%' , #{tradeId} , '%')
AND fpd.P_TRADE_ID LIKE CONCAT('%' , #{pTradeId} , '%')
AND A.Book_Type = #{bookType}
AND A.BUS_VOUCHNUM LIKE CONCAT('%' , #{busVouchnum} , '%')
AND A.BOOK_DATE >= #{happenDateBegin}
AND A.BOOK_DATE <= #{happenDateEnd}
ORDER BY A.BOOK_DATE DESC, A.BUS_VOUCHNUM DESC

SELECT A.BOOK_DATE AS bookDate, B.HAPPEN_DATE AS happenDate, A.BOOKSET_ID AS booksetId, bb.BOOKSET_NAME AS booksetName, A.BUS_VOUCHNUM AS busVouchnum,
IFNULL(B.DETAIL_SUBJECT_NO,B.SUBJECT_NO) AS subjectNo, IFNULL(bbd.DETAIL_SUBJECT_NAME,bs.SUBJECT_NAME) AS subjectName,
B.CD_FLAG AS cdFlag, B.ccy AS ccy, B.HAPPEN_AMT AS happenAmt, B.B_CCY as bCcy, B.B_HAPPEN_AMT as bHappenAmt, B.HAPPEN_NUMBER AS happenNumber, bs.bal_flag AS balanceDirection, '' balanceAmount, B.BUSI_ID AS busiId, IFNULL(fp.FINPROD_ABBR, stl.acct_name) as busiName,
A.COM_TABLE_ID AS tableId, B.TRADE_ID AS tradeId, fpd.P_TRADE_ID AS pTradeId, B.Book_Type AS bookType, A.OFFSET_FLAG AS offsetFlag, A.VOUCH_REMARK AS vouchRemark, A.VOUCH_NUM AS vouchNum, B.CREATE_USER as createUser, I.CORE_ID as coreId, I.TASK_STATUS as taskStatus FROM bok_VOUCH_DETAIL B JOIN bok_VOUCH_MAIN A ON A.VOUCH_NUM = B.VOUCH_NUM LEFT JOIN INTERF_CORE_BANK_VOUCHER I ON I.VOUCH_NUM = A.VOUCH_NUM LEFT JOIN BOK_BOOKSET bb ON BB.BOOKSET_ID = A.BOOKSET_ID LEFT JOIN BOK_SUBJECT bs ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL AND bs.SUBJECT_NO = B.SUBJECT_NO LEFT JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = A.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = B.DETAIL_SUBJECT_NO LEFT JOIN trd_PRODUCT_DEAL fpd ON fpd.TRADE_ID = B.TRADE_ID lEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = B.BUSI_ID left join STL_CAPACCT_INFO stl on stl.acct_no = B.BUSI_ID WHERE EXISTS( SELECT b2.VOUCH_NUM FROM BOK_VOUCH_DETAIL B2 WHERE B2.VOUCH_NUM = A.VOUCH_NUM ) AND bb.BOOKSET_TYPE in (#{booksetType} ,#{booksetType2})
AND A.BOOKSET_ID IN
#{item}
AND A.COM_TABLE_ID IN
#{tableId}
AND ( B.BUSI_ID LIKE CONCAT('%' , #{busiId} , '%') )
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
AND B.TRADE_ID LIKE CONCAT('%' , #{tradeId} , '%')
AND fpd.P_TRADE_ID LIKE CONCAT('%' , #{pTradeId} , '%')
AND B.Book_Type = #{bookType}
AND A.BUS_VOUCHNUM LIKE CONCAT('%' , #{busVouchnum} , '%')
AND B.HAPPEN_DATE >= #{happenDateBegin}
AND B.HAPPEN_DATE <= #{happenDateEnd}
ORDER BY A.BOOK_DATE DESC, A.BUS_VOUCHNUM DESC
